// Ordnet die Jev-Antwort ein: ok, Wiederholung (nur bei 429 und 529, hoechstens 1 zweiter Versuch) oder Ausfall.
// Versuch 1 kommt aus "K1-Bezug prüfen", Versuch 2 aus "K1-Bezug erneut prüfen"; dann laeuft dieser Knoten ein zweites Mal ($runIndex 1).
const cfg = $('Konfiguration [Edit Fields]').first().json;
const res = $input.first().json;
const attempt = $runIndex + 1;
let code = Number(res.statusCode ?? 0);
// Testschalter: stoer=jev429 im Testkuerzel simuliert beim 1. Versuch einen 429, um den Wiederholweg zu pruefen (nur manuelle Laeufe).
if (cfg.stoerung === 'jev429' && attempt === 1) code = 429;
const retryable = code === 429 || code === 529;
let decision = 'fail';
if (code === 200) decision = 'ok';
else if (retryable && attempt === 1) decision = 'retry';
const err = decision === 'fail' ? ('HTTP ' + code + ': ' + JSON.stringify(res.body ?? '').slice(0, 150)) : '';
return [{ json: { decision, status_code: code, jev_attempts: attempt, body: res.body ?? null, jev_error: err } }];

// Misst die Werkzeugwahl aus den Zwischenschritten des Agenten (tatsaechliche Aufrufe dieser Ausfuehrung).
// tools_called nennt die Werkzeuge in der Reihenfolge der Aufrufe, tool_reason fasst sie als "gemessen: ..." zusammen.
// Fehlererkennung je Werkzeug am erwarteten Rueckgabeformat (FAQ: Kopfzeile, Auftrag und Vormerkung: JSON mit dem Feld status, auch wenn es als Text mit maskierten Anfuehrungszeichen ankommt, Wissensbasis: Quellzeile, Feiertage: Datum).
// Sperre (keine Erfolgsmeldung ohne bestaetigtes Werkzeugergebnis): nennt die Antwort eine Ticketnummer oder eine Weiterleitung,
// die weder dieser Lauf noch ein frueherer Lauf der Sitzung (Spalte action im Protokoll) bestaetigt hat, wird sie durch einen ehrlichen Hinweis ersetzt.
// Als Weiterleitung zaehlt eine positive Aussage (auch angekuendigt: "leite ... weiter", oder die Woerter Eilmeldung und Eskalation).
// Verneinungen ("keine Eilmeldung noetig"), Bedingungen ("falls", "wenn") und Rueckfragen sind keine Behauptung; sie werden je Satz geprueft.
const item = $input.first().json;
const raw = String(item.output ?? '').trim();
let output = raw;
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
const calls = steps.filter(s => s && s.action && s.action.tool).map(s => ({ tool: s.action.tool, obs: typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation ?? '') }));
const isError = (c) => {
  if (c.tool === 'K1_Antwortkatalog') return !c.obs.includes('id,kategorie');
  if (c.tool === 'Auftragsstand') return !/\\?"status\\?"\s*:\s*\\?"(gefunden|fehlt|ungueltig|unbekannt)\\?"/.test(c.obs);
  if (c.tool === 'Teamvormerkung') return !/\\?"status\\?"\s*:\s*\\?"(erfasst|fehlt)\\?"/.test(c.obs);
  if (c.tool === 'Eilmeldung_ans_Team') return !/accepted/i.test(c.obs);
  if (c.tool === 'K1_Technikwissen') return !c.obs.includes('Quelle:');
  if (c.tool === 'Feiertage_nachschlagen') return !/\d{4}-\d{2}-\d{2}/.test(c.obs);
  return /error|fehler/i.test(c.obs);
};
const toolErrors = calls.filter(isError).length;
const toolReason = 'gemessen: ' + (calls.length ? calls.map(x => x.tool).join(', ') : 'kein Werkzeug');
const tickets = calls.filter(c => c.tool === 'Teamvormerkung').map(c => (c.obs.match(/K1-T-\d{5}/) || [])[0]).filter(Boolean);
const escalated = calls.some(c => c.tool === 'Eilmeldung_ans_Team' && !isError(c));
const actions = tickets.map(t => 'ticket:' + t).concat(escalated ? ['eskalation:gesendet'] : []);
const claimedTickets = output.match(/K1-T-\d{5}/g) || [];
const prior = $('Verlauf der Sitzung lesen [Supabase]').all().map(i => String(i.json.action ?? '')).join(',');
const priorTickets = prior.match(/K1-T-\d{5}/g) || [];
const priorEscalated = /eskalation:gesendet/.test(prior);
const unconfirmedTicket = claimedTickets.some(t => !tickets.includes(t) && !priorTickets.includes(t));
const verbClaim = /(weitergeleitet|weitergegeben|weiterleiten|weitergeben|leite [^.!?]{0,80}weiter|gebe [^.!?]{0,80}weiter|eskalier|an das (K1-)?Team (geschickt|gesendet)|(E-)?Mail an das)/i;
const nounClaim = /((eilmeldung|eskalation)[^.!?]{0,80}(gesendet|versendet|versandt|ausgel[oö]st|rausgegangen|raus ?gegangen|verschickt|abgeschickt|losgeschickt|unterwegs|ist raus|angekommen|eingegangen|soeben|bereits|wurde)|(gesendet|versendet|ausgel[oö]st|verschickt|abgeschickt|losgeschickt)[^.!?]{0,80}(eilmeldung|eskalation)|\b(habe|hab|haben)\b[^.!?]{0,60}(eilmeldung|eskalation))/i;
const noClaim = /(\bnicht\b(?! nur)|\bkein\w*|\bohne\b|\bnie\b|\bniemals\b|\bwenn\b|\bfalls\b|\bsobald\b|\bsofern\b|\bsollte\w*|\bw(?:ü|ue)rde\w*|\bk[oö]nnte\w*|\bm[oö]chtest\b|\bwillst\b)/i;
const sentences = output.match(/(?:[^.!?;\n]|\.(?=\d))+[.!?;]*/g) || [];
const claimsEscalation = sentences.some(s => !/\?/.test(s) && s.split(/\s+(?:aber|jedoch|sondern|dafür|stattdessen)\s+/i).some(t => (verbClaim.test(t) || nounClaim.test(t)) && !noClaim.test(t)));
const unconfirmedEscalation = claimsEscalation && !escalated && !priorEscalated;
let guard = '';
if (unconfirmedTicket || unconfirmedEscalation) {
  guard = unconfirmedTicket ? 'Ticketnummer ohne Bestätigung ersetzt' : 'Weiterleitung ohne Bestätigung ersetzt';
  output = 'Das konnte ich gerade nicht sicher erledigen. Bitte wende dich direkt an das K1-Team über den Kanal, über den du Aufträge schickst.';
}
const folge = $('Folgefrage vermerken [Edit Fields]');
const jevNode = $('Jev-Werte übernehmen [Edit Fields]');
const jevOk = jevNode.isExecuted && jevNode.first().json.jev_noul >= 0;
const route = folge.isExecuted ? 'folgefrage' : (jevOk ? 'agent' : 'ohne_jev');
const status = (toolErrors > 0 || guard) ? 'tool_error' : (route === 'ohne_jev' ? 'fallback' : 'ok');
return [{ json: {
  output, route, tool_called: calls.length > 0, tool_calls_count: calls.length,
  tools_called: calls.map(c => c.tool).join(','),
  tool_reason: guard ? toolReason + ' | Sperre: ' + guard : toolReason,
  action: actions.join(',') || null, status
} }];

// Baut aus jedem Weg (agent, folgefrage, ohne_jev, fremd, rueckfrage, ausfall) eine einheitliche Protokollzeile.
// Fehlende Werte (Jev nicht gelaufen, Kosten nicht geliefert) stehen als leer (null), nie als 0.
// Tokens des Gratismodells bleiben leer: ein Code-Knoten erreicht die Ausgaben des Modell-Unterknotens nicht; sie stehen im Ausfuehrungsprotokoll.
const cfg = $('Konfiguration [Edit Fields]').first().json;
const cur = $input.first().json;
const jevNode = $('Jev-Werte übernehmen [Edit Fields]');
const jev = jevNode.isExecuted ? jevNode.first().json : null;
const down = $('Jev-Ausfall vermerken [Edit Fields]');
const attempts = jev ? jev.jev_attempts : (down.isExecuted ? down.first().json.jev_attempts : null);
const usesModel = ['agent', 'ohne_jev', 'ausfall', 'folgefrage'].includes(cur.route);
const num = (v) => (typeof v === 'number' && v >= 0) ? v : null;
return [{ json: {
  output: cur.output,
  execution_id: $execution.id,
  workflow_name: $workflow.name,
  workflow_version: cfg.workflow_version,
  prompt_version: cfg.prompt_version,
  test_id: cfg.test_id || null,
  session_id: cfg.session_id,
  question: cfg.question,
  jev_noul: jev ? num(jev.jev_noul) : null,
  jev_anliegen: jev && jev.jev_anliegen ? jev.jev_anliegen : null,
  jev_anliegen_conf: jev ? num(jev.jev_anliegen_conf) : null,
  jev_attempts: attempts,
  route: cur.route,
  tool_called: cur.tool_called === true,
  tool_calls_count: cur.tool_calls_count ?? 0,
  tools_called: cur.tools_called || null,
  tool_reason: cur.tool_reason,
  action: cur.action ?? null,
  model: usesModel ? cfg.agent_model : null,
  memory_setting: usesModel ? cfg.memory_setting : null,
  tokens_in: null,
  tokens_out: null,
  cost_usd: jev ? num(jev.jev_cost_usd) : null,
  cost_usd_listprice: null,
  duration_ms: Date.now() - cfg.start_time,
  status: cur.status
} }];
